# For each column, group 8-rows into consecutive segments
out = [[0]*15 for _ in range(10)]

for c in range(15):
    # Find all groups of consecutive 8s
    groups = []
    r = 0
    while r < 17:
        if test_input[r][c] == 8 and r != 8:  # skip row 8
            start_r, end_r = r, r
            while r < 17 and test_input[r][c] == 8:
                r += 1
            end_r = r - 1
            if end_r < 17:  # valid group
                groups.append((start_r, end_r))
        else:
            r += 1

    # Map groups to output slots: (0,1), (4,5), (8,9), ...
    for slot_idx, (start_r, end_r) in enumerate(groups):
        output_slot = slot_idx * 2  # row indices in output: 0, 4, 8, ...
        if output_slot <= 8:  # valid in 0-9
            for local_r in range(start_r, end_r + 1):
                if test_input[local_r][c] == 8:
                    out[output_slot + (local_r - start_r)][c] = 2

print("Output:")
for i, row in enumerate(out):
    print(f"Row {i}: {row}")

